# Use docker DNS via nonstd: query DNS server 127.0.0.11 directly for prices.internal using raw UDP
import socket, struct, random
def query(name, server="127.0.0.11"):
    tid=random.randint(0,65535)
    q=b"".join(bytes([len(l)])+l.encode() for l in name.split("."))+b"\x00"
    pkt=struct.pack(">HHHHHH",tid,0x0100,1,0,0,0)+q+struct.pack(">HH",1,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(pkt,(server,53))
    data,_=s.recvfrom(512)
    # parse answers
    i=12
    def skipname(d,i):
        if d[i]&0xC0==0xC0: return i+2
        while d[i]!=0: i+=d[i]+1
        return i+1
    i=skipname(data,i); i+=4
    ancount=struct.unpack(">H",data[6:8])[0]
    print(name,"ancount",ancount)
    for _ in range(ancount):
        i=skipname(data,i)
        typ,cl,ttl,rdlen=struct.unpack(">HHIH",data[i:i+10]); i+=10
        rd=data[i:i+rdlen]
        if typ==1: print(" A:",socket.inet_ntoa(rd))
        elif typ in (5,): print(" CNAME:",b".".join(x[1:] for x in rd.split(b".")[:-1] if False))
        i+=rdlen
for n in ["prices.internal","internal","_services._dns-sd._udp.internal"]:
    try: query(n)
    except Exception as e: print(n,e)
